import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider } from './context/AuthContext';
import { CartProvider } from './context/CartContext';
import { WishlistProvider } from './context/WishlistContext';

import Navbar from './components/Navbar';
import Footer from './components/Footer';
import WhatsAppButton from './components/WhatsAppButton';

import HomePage from './pages/HomePage';
import ShopPage from './pages/ShopPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import OrderSuccessPage from './pages/OrderSuccessPage';
import LoginPage from './pages/LoginPage';
import OrderHistoryPage from './pages/OrderHistoryPage';
import WishlistPage from './pages/WishlistPage';
import AdminDashboard from './pages/AdminDashboard';
import ProfilePage from './pages/ProfilePage';

import './index.css';

const Layout = ({ children }) => (
  <>
    <Navbar />
    <main style={{ minHeight: '60vh' }}>{children}</main>
    <Footer />
    <WhatsAppButton phone="919849854853" />
  </>
);

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <CartProvider>
          <WishlistProvider>
            <Toaster
              position="top-center"
              toastOptions={{
                duration: 3000,
                style: {
                  fontFamily: 'var(--font-display)',
                  fontWeight: 600,
                  fontSize: '15px',
                  borderRadius: '12px',
                  padding: '14px 20px',
                }
              }}
            />
            <Routes>
              <Route path="/admin" element={<AdminDashboard />} />
              <Route path="/login" element={<Layout><LoginPage /></Layout>} />
              <Route path="/" element={<Layout><HomePage /></Layout>} />
              <Route path="/shop" element={<Layout><ShopPage /></Layout>} />
              <Route path="/cart" element={<Layout><CartPage /></Layout>} />
              <Route path="/checkout" element={<Layout><CheckoutPage /></Layout>} />
              <Route path="/order-success" element={<Layout><OrderSuccessPage /></Layout>} />
              <Route path="/orders" element={<Layout><OrderHistoryPage /></Layout>} />
              <Route path="/wishlist" element={<Layout><WishlistPage /></Layout>} />
              <Route path="/profile" element={<Layout><ProfilePage /></Layout>} />
              <Route path="*" element={<Layout>
                <div style={{ textAlign: 'center', padding: '80px 20px' }}>
                  <div style={{ fontSize: 80 }}>🌿</div>
                  <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 30, color: 'var(--gray-600)', marginTop: 16 }}>Page Not Found</h1>
                  <a href="/" className="btn-primary" style={{ display: 'inline-flex', marginTop: 20 }}>Go to Home</a>
                </div>
              </Layout>} />
            </Routes>
          </WishlistProvider>
        </CartProvider>
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;
